/// The tables and indexes of a result bundle's `database.sqlite3`, as `xcodebuild test` of Xcode 27.0
/// creates them (`xctest_experiments.py` `xcresult-pass`, docs/formats/xcresult.md), which
/// `xcresulttool get test-results` reads.
enum ResultBundleSchema {
    static let statements = [
        "CREATE TABLE RepetitionPolicies (totalRepetitions INTEGER, repetition INTEGER, repetitionModeString TEXT)",
        "CREATE TABLE TestPlans (name TEXT)",
        "CREATE TABLE Platforms (identifier TEXT, userDescription TEXT)",
        "CREATE TABLE TestValues (typeName TEXT, orderInParent INTEGER, label TEXT, description TEXT, debugDescription TEXT, fullyQualifiedTypeName TEXT, isCollection INTEGER, children TEXT)",
        "CREATE TABLE SDKs (operatingSystemVersion TEXT, identifier TEXT, isInternal INTEGER, name TEXT)",
        "CREATE TABLE SkipNotices (message TEXT, timestamp REAL, lineNumber INTEGER, fileName TEXT)",
        "CREATE TABLE SourceCodeLocations (filePath TEXT, lineNumber INTEGER)",
        "CREATE TABLE Expressions (testValue_fk INTEGER REFERENCES TestValues, subexpressions TEXT, sourceCode TEXT)",
        "CREATE TABLE DeveloperTools (xcodeBuildVersion TEXT, xcodeVersion TEXT)",
        "CREATE TABLE UserInfos (identifier INTEGER)",
        "CREATE TABLE DocumentLocations (className TEXT, url TEXT)",
        "CREATE TABLE SourceCodeSymbolInfos (location_fk INTEGER REFERENCES SourceCodeLocations, symbolName TEXT, imageName TEXT)",
        "CREATE TABLE Invocations (timestamp REAL, scheme TEXT, uniqueIdentifier TEXT, workspacePath TEXT)",
        "CREATE TABLE SourceCodeContexts (location_fk INTEGER REFERENCES SourceCodeLocations)",
        "CREATE TABLE UserInfoKeyValues (userInfo_fk INTEGER NOT NULL REFERENCES UserInfos, stringValue TEXT, key TEXT, intValue INTEGER, doubleValue REAL)",
        "CREATE TABLE Devices (isConcreteDevice INTEGER, operatingSystemVersionWithBuildNumber TEXT, modelCode TEXT, nativeArchitecture TEXT, ramSizeInMegabytes INTEGER, physicalCPUCoresPerPackage INTEGER, modelUTI TEXT, cpuKind TEXT, cpuCount INTEGER, logicalCPUCoresPerPackage INTEGER, isWireless INTEGER, operatingSystemVersion TEXT, cpuSpeedInMHz INTEGER, identifier TEXT, modelName TEXT, busSpeedInMHz INTEGER, platform_fk INTEGER REFERENCES Platforms, name TEXT)",
        "CREATE TABLE TestErrors (code INTEGER, userInfo_fk INTEGER REFERENCES UserInfos, domain TEXT)",
        "CREATE TABLE TestPlanConfigurations (testPlan_fk INTEGER NOT NULL REFERENCES TestPlans, name TEXT, language TEXT, region TEXT)",
        "CREATE TABLE Testables (externalTestReference TEXT, identifierURL TEXT, testPlan_fk INTEGER NOT NULL REFERENCES TestPlans, orderInTestPlan INTEGER, name TEXT, projectRelativePath TEXT, testKind TEXT)",
        "CREATE TABLE TestSuites (name TEXT, testable_fk INTEGER REFERENCES Testables, orderInParent INTEGER, parentSuite_fk INTEGER REFERENCES TestSuites, identifier TEXT, identifierURL TEXT, summary TEXT)",
        "CREATE INDEX TestSuites_parentSuite_fk_index ON TestSuites(parentSuite_fk)",
        "CREATE INDEX TestSuites_testable_fk_index ON TestSuites(testable_fk)",
        "CREATE TABLE SourceCodeFrames (context_fk INTEGER REFERENCES SourceCodeContexts, address TEXT, symbolInfo_fk INTEGER REFERENCES SourceCodeSymbolInfos, orderInContainer INTEGER)",
        "CREATE INDEX SourceCodeFrames_context_fk_index ON SourceCodeFrames(context_fk)",
        "CREATE TABLE RunDestinations (architecture TEXT, device_fk INTEGER REFERENCES Devices, sdk_fk INTEGER REFERENCES SDKs, name TEXT)",
        "CREATE TABLE TestCases (orderInTestSuite INTEGER, name TEXT, testSuite_fk INTEGER NOT NULL REFERENCES TestSuites, identifier TEXT, identifierURL TEXT, summary TEXT)",
        "CREATE INDEX TestCases_testSuite_fk_index ON TestCases(testSuite_fk)",
        "CREATE TABLE TestDocumentations (content TEXT, orderInParent INTEGER, testCase_fk INTEGER REFERENCES TestCases, testSuite_fk INTEGER REFERENCES TestSuites, format TEXT)",
        "CREATE TABLE TestCaseResultsByDestinationAndConfiguration (configuration_fk INTEGER REFERENCES TestPlanConfigurations, result TEXT, testCase_fk INTEGER NOT NULL REFERENCES TestCases, destination_fk INTEGER REFERENCES RunDestinations)",
        "CREATE INDEX TestCaseResultsByDestinationAndConfiguration_testCase_fk_index ON TestCaseResultsByDestinationAndConfiguration(testCase_fk)",
        "CREATE TABLE IssueTrackingMetadata (url TEXT, title TEXT, testCase_fk INTEGER REFERENCES TestCases, orderInParent INTEGER, matchIdentifier TEXT, testSuite_fk INTEGER REFERENCES TestSuites, identifier TEXT)",
        "CREATE TABLE Actions (diagnosticsRef TEXT, invocation_fk INTEGER NOT NULL REFERENCES Invocations, finished REAL, runDestination_fk INTEGER REFERENCES RunDestinations, developerTools_fk INTEGER REFERENCES DeveloperTools, testPlan_fk INTEGER NOT NULL REFERENCES TestPlans, host_fk INTEGER REFERENCES Devices, orderInInvocation INTEGER, name TEXT, started REAL)",
        "CREATE TABLE BuildIssues (severity INTEGER, documentLocation_fk INTEGER REFERENCES DocumentLocations, producingTarget TEXT, issueType TEXT, action_fk INTEGER NOT NULL REFERENCES Actions, message TEXT, orderInAction INTEGER)",
        "CREATE TABLE Parameters (orderInTestCase INTEGER, label TEXT, testCase_fk INTEGER NOT NULL REFERENCES TestCases, typeName TEXT, name TEXT)",
        "CREATE TABLE TestTags (testCase_fk INTEGER REFERENCES TestCases, name TEXT, testSuite_fk INTEGER REFERENCES TestSuites)",
        "CREATE TABLE TestPlanRuns (action_fk INTEGER NOT NULL REFERENCES Actions, testPlan_fk INTEGER NOT NULL REFERENCES TestPlans, orderInAction INTEGER, configuration_fk INTEGER NOT NULL REFERENCES TestPlanConfigurations)",
        "CREATE TABLE TestableRuns (testPlanRun_fk INTEGER NOT NULL REFERENCES TestPlanRuns, orderInTestPlanRun INTEGER, diagnosticsDirectoryName TEXT, testable_fk INTEGER NOT NULL REFERENCES Testables)",
        "CREATE TABLE TestSuiteRuns (testableRun_fk INTEGER REFERENCES TestableRuns, parentSuiteRun_fk INTEGER REFERENCES TestSuiteRuns, duration REAL, testSuite_fk INTEGER NOT NULL REFERENCES TestSuites, orderInParent INTEGER)",
        "CREATE INDEX TestSuiteRuns_testableRun_fk_index ON TestSuiteRuns(testableRun_fk)",
        "CREATE INDEX TestSuiteRuns_parentSuiteRun_fk_index ON TestSuiteRuns(parentSuiteRun_fk)",
        "CREATE INDEX TestSuiteRuns_testSuite_fk_index ON TestSuiteRuns(testSuite_fk)",
        "CREATE TABLE TestCaseRuns (dynamicTestParameters_fk INTEGER REFERENCES UserInfos, repetitionPolicy_fk INTEGER REFERENCES RepetitionPolicies, duration REAL, identifierURL TEXT, testSuiteRun_fk INTEGER NOT NULL REFERENCES TestSuiteRuns, orderInTestSuiteRun INTEGER, testCase_fk INTEGER NOT NULL REFERENCES TestCases, skipNotice_fk INTEGER REFERENCES SkipNotices, result TEXT)",
        "CREATE INDEX TestCaseRuns_testSuiteRun_fk_index ON TestCaseRuns(testSuiteRun_fk)",
        "CREATE INDEX TestCaseRuns_testCase_fk_index ON TestCaseRuns(testCase_fk)",
        "CREATE TABLE TestIssues (orderInOwner INTEGER, testCaseRun_fk INTEGER REFERENCES TestCaseRuns, expression_fk INTEGER REFERENCES Expressions, uuid TEXT, timestamp REAL, detailedDescription TEXT, issueType TEXT, sourceCodeContext_fk INTEGER REFERENCES SourceCodeContexts, testSuiteRun_fk INTEGER REFERENCES TestSuiteRuns, sanitizedDescription TEXT, compactDescription TEXT, isTopLevel INTEGER, associatedError_fk INTEGER REFERENCES TestErrors)",
        "CREATE INDEX TestIssues_testSuiteRun_fk_index ON TestIssues(testSuiteRun_fk)",
        "CREATE INDEX TestIssues_testCaseRun_fk_index ON TestIssues(testCaseRun_fk)",
        "CREATE TABLE ExpectedFailures (orderInOwner INTEGER, uuid TEXT, issue_fk INTEGER REFERENCES TestIssues, testCaseRun_fk INTEGER REFERENCES TestCaseRuns, failureReason TEXT, testSuiteRun_fk INTEGER REFERENCES TestSuiteRuns, isTopLevelFailure INTEGER)",
        "CREATE INDEX ExpectedFailures_testSuiteRun_fk_index ON ExpectedFailures(testSuiteRun_fk)",
        "CREATE INDEX ExpectedFailures_testCaseRun_fk_index ON ExpectedFailures(testCaseRun_fk)",
        "CREATE TABLE PerformanceMetrics (maxPercentRegression REAL, unitOfMeasurement TEXT, testCaseRun_fk INTEGER NOT NULL REFERENCES TestCaseRuns, maxRegression REAL, measurements TEXT, baselineAverage REAL, maxPercentRelativeStandardDeviation REAL, identifier TEXT, displayName TEXT, baselineName TEXT, maxStandardDeviation REAL, polarity TEXT, orderInTestCase INTEGER)",
        "CREATE TABLE Activities (parent_fk INTEGER REFERENCES Activities, testCaseRun_fk INTEGER REFERENCES TestCaseRuns, activityType TEXT, orderInParent INTEGER, title TEXT, warningIDs TEXT, uuid TEXT, expectedFailureIDs TEXT, startTime REAL, failureIDs TEXT, finishTime REAL)",
        "CREATE INDEX Activities_testCaseRun_fk_index ON Activities(testCaseRun_fk)",
        "CREATE TABLE Arguments (testCaseRun_fk INTEGER NOT NULL REFERENCES TestCaseRuns, testValue_fk INTEGER NOT NULL REFERENCES TestValues, identifier TEXT, orderInTestCaseRun INTEGER, parameter_fk INTEGER REFERENCES Parameters)",
        "CREATE INDEX Arguments_testCaseRun_fk_index ON Arguments(testCaseRun_fk)",
        "CREATE TABLE Attachments (lifetime TEXT, uuid TEXT, inActivityIdentifier INTEGER, uniformTypeIdentifier TEXT, name TEXT, testIssue_fk INTEGER REFERENCES TestIssues, xcResultKitPayloadRefId TEXT, userInfo_fk INTEGER REFERENCES UserInfos, activity_fk INTEGER REFERENCES Activities, timestamp REAL, filenameOverride TEXT)"
    ]
}
